std::vector<float>render(GillDynamicsProcessor&p,int samples,int block=128,bool bypass=false){std::vector<float>out;out.reserve(samples);juce::AudioBuffer<float>b(p.getTotalNumOutputChannels(),block);juce::MidiBuffer m;for(int at=0;at<samples;at+=block){const int n=std::min(block,samples-at);b.setSize(b.getNumChannels(),n,false,false,true);for(int c=0;c<b.getNumChannels();++c)for(int i=0;i<n;++i)b.setSample(c,i,voice(at+i,p.uiRate.load(),c));if(bypass)p.processBlockBypassed(b,m);else p.processBlock(b,m);out.insert(out.end(),b.getReadPointer(0),b.getReadPointer(0)+n);}return out;}
