void metadata(DynKind k){auto p=std::make_unique<GillDynamicsProcessor>(k);product=p->getName().toStdString();check(p->hasEditor()&&!p->acceptsMidi()&&p->getNumPrograms()==12&&p->getBypassParameter()==p->apvts.getParameter("bypass"),"metadata, bypass and12factory programs");bool all=true;std::vector<std::vector<float>>states;for(int i=0;i<12;++i){p->setCurrentProgram(i);all&=p->getCurrentProgram()==i&&p->presetMatches();states.push_back(vals(*p));++presetsTested;prepare(*p);auto out=render(*p,12000);all&=std::all_of(out.begin(),out.end(),[](float x){return std::isfinite(x)&&std::abs(x)<100;});++configs;}for(int i=0;i<12;++i)for(int j=i+1;j<12;++j)all&=states[i]!=states[j];check(all,"every preset is distinct and processes finite audio");p->setValue(p->definitions.front().id,p->definitions.front().lo+.37f*(p->definitions.front().hi-p->definitions.front().lo),false);juce::MemoryBlock s;p->getStateInformation(s);auto q=std::make_unique<GillDynamicsProcessor>(k);q->setStateInformation(s.getData(),static_cast<int>(s.getSize()));check(vals(*p)==vals(*q)&&q->getCurrentProgram()==p->getCurrentProgram(),"all parameters and custom program round-trip");prepare(*p);prepare(*q);check(render(*p,16000,127)==render(*q,16000,127),"recalled state produces identical processed audio");const auto old=vals(*q);const char junk[]{1,2,3,0};q->setStateInformation(junk,4);check(vals(*q)==old,"malformed state leaves current controls intact");auto xml=juce::AudioProcessor::getXmlFromBinary(s.getData(),static_cast<int>(s.getSize()));auto tree=juce::ValueTree::fromXml(*xml);tree.getChild(0).setProperty("value","NaN",nullptr);juce::MemoryBlock bad;juce::AudioProcessor::copyXmlToBinary(*tree.createXml(),bad);q->setStateInformation(bad.getData(),static_cast<int>(bad.getSize()));check(vals(*q)==old,"nonfinite parameter in state is rejected");}
