struct Components{
    std::vector<juce::Slider*>sliders;std::vector<juce::ComboBox*>combos;std::vector<juce::Button*>buttons;
    std::vector<juce::Component*>all;
    std::vector<juce::Component::SafePointer<juce::Component>>life;
    bool allAlive()const{return std::all_of(life.begin(),life.end(),[](const auto&component){return component!=nullptr;});}
    void scan(juce::Component&c){all.push_back(&c);life.emplace_back(&c);if(auto*s=dynamic_cast<juce::Slider*>(&c))sliders.push_back(s);if(auto*x=dynamic_cast<juce::ComboBox*>(&c))combos.push_back(x);if(auto*b=dynamic_cast<juce::Button*>(&c))buttons.push_back(b);for(auto*child:c.getChildren())scan(*child);}
};
struct HostListener final:juce::AudioProcessorListener{
    int begins=0,ends=0,changes=0;bool ordered=true;std::array<int,64>depth{};
    void audioProcessorParameterChanged(juce::AudioProcessor*,int,float)override{++changes;}
    void audioProcessorChanged(juce::AudioProcessor*,const ChangeDetails&)override{}
    void audioProcessorParameterChangeGestureBegin(juce::AudioProcessor*,int i)override{++begins;if(i>=0&&i<64)ordered=ordered&&++depth[static_cast<size_t>(i)]==1;}
    void audioProcessorParameterChangeGestureEnd(juce::AudioProcessor*,int i)override{++ends;if(i>=0&&i<64)ordered=ordered&&--depth[static_cast<size_t>(i)]==0;}
    bool closed()const{return ordered&&begins==ends&&std::all_of(depth.begin(),depth.end(),[](int d){return d==0;});}
};
